// helpers
const inp = $input.first().json;
const empty = v => v === undefined || v === null || v === '' || (Array.isArray(v) && v.length === 0);
const pick = (keys) => { const o = {}; for (const k of keys) if (!empty(inp[k])) o[k] = inp[k]; return o; };
const asObj = (v) => { if (empty(v)) return {}; if (typeof v === 'string') { try { return JSON.parse(v); } catch (e) { throw new Error('EFX E_VALIDATION: JSON field is not valid JSON'); } } return v; };
const asArr = (v) => empty(v) ? [] : (Array.isArray(v) ? v : String(v).split(',').map(s => s.trim()).filter(Boolean));
const bool = (v, d) => empty(v) ? d : (v === true || String(v).toLowerCase() === 'true');
const passthru = { actor: empty(inp.actor) ? undefined : inp.actor, idempotencyKey: empty(inp.idempotencyKey) ? '' : String(inp.idempotencyKey) };

const REQUIRED = ["firstName","lastName","siteName","managerEmail","managerName","position"];
const OPTIONAL = ["reqName","reqEmail","requesterName","requesterEmail","positionTitle","reportingManagerEmail","reportingManagerName","dateRequested","middleName","preferredName","systems","equipment","googleEmail","googleDomain","computerRequestType","computerType","computerPreviousUser","computerPreviousType","computerSerialNumber","office365Required","creditCardUSA","creditCardLimitUSA","creditCardCanada","creditCardLimitCanada","creditCardHomeDepot","creditCardLimitHomeDepot","phoneRequestType","phonePreviousUser","phonePreviousNumber","bossJobSites","bossCostSheet","bossCostSheetJobs","bossTripReports","bossGrievances","jonasJobNumbers","comments","adpSites","department","purchasingSites","adpSalaryAccess","bossTrainingOnly","hireDate","newHireOrRehire","employeeType","employmentType","jobSiteNumber","systemAccess","jrRequired","jrAssignment","plan306090"];
const DYN = [];
const data = Object.assign({}, asObj(inp.extra), pick(REQUIRED.concat(OPTIONAL)));
const missing = REQUIRED.filter(k => empty(data[k]));
if (missing.length) throw new Error('EFX E_VALIDATION: equipment_request missing required field(s): ' + missing.join(', '));
const unknown = Object.keys(data).filter(k => !REQUIRED.includes(k) && !OPTIONAL.includes(k) && !DYN.some(p => k.startsWith(p)));
if (unknown.length) throw new Error('EFX E_VALIDATION: equipment_request unknown field(s) (not in contract): ' + unknown.join(', '));
if (!empty(inp.systems)) data.systems = asArr(inp.systems);
if (!empty(inp.equipment)) data.equipment = asArr(inp.equipment);
if (empty(data.dateRequested)) data.dateRequested = $now.toFormat('yyyy-MM-dd');
const options = { include: bool(inp.includeRecord, false) ? ['record'] : [], allowUnverified: bool(inp.allowUnverified, false) };
return [{ json: Object.assign({ fn: 'n8n_createEquipmentRequest', args: [data, options] }, passthru) }];
